```ts
import { computed, effect, Injectable, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private _items = signal<WatchItem[]>(
        this.rehydrate(JSON.parse(localStorage.getItem(this.KEY) ?? '[]'))
    );

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.seen).length)

    constructor() {
        effect(() => {
            localStorage.setItem(this.KEY, JSON.stringify(this._items()));
        });
    }

    private rehydrate(raw: unknown): WatchItem[] {
        if (!Array.isArray(raw)) return [];
        const items: WatchItem[] = [];
        for (const entry of raw) {
            if (!entry || typeof entry !== 'object') continue;
            const record = entry as Record<string, unknown>;
            const seen =
                typeof record.seen === 'boolean'
                    ? record.seen
                    : typeof record.watched === 'boolean'
                      ? record.watched
                      : false;
            items.push({
                id: record.id as number,
                title: record.title as string,
                seen,
                poster_path: record.poster_path as string | null | undefined,
                release_date: record.release_date as string | undefined,
            });
        }
        return items;
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id)
                ? items
                : [...items, {
                    id: movie.id,
                    title: movie.title,
                    poster_path: movie.poster_path,
                    release_date: movie.release_date,
                    seen: false,
                }]
        );
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            items.map(m => m.id === id ? { ...m, seen: !m.seen } : m)
        );
    }
}
```

